{"type":"item.completed","item":{"id":"item_1","type":"agent_message","text":"{\"tool\":\"sql_query\",\"arguments\":{\"company_name\":\"CLOSE_fin_05\",\"table_name\":\"ledger\",\"query\":\"WITH ranked AS (SELECT kind,event_key,invoice_id,vendor,business_date,revision,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den,ROW_NUMBER() OVER (PARTITION BY kind,event_key ORDER BY revision DESC) AS rn FROM ledger WHERE datetime(recorded_at)<=datetime('2026-10-24T12:00:00') AND date(business_date)<=date('2026-10-23')), active AS (SELECT kind,event_key,invoice_id,vendor,business_date,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den FROM ranked WHERE rn=1 AND status<>'void'), amounts AS (SELECT i.event_key,i.business_date,i.currency,i.terms_code,i.discount_until,MAX(0,MAX(0,i.amount_minor-COALESCE((SELECT SUM(p.amount_minor) FROM active p WHERE p.kind='payment' AND p.invoice_id=i.event_key),0)-COALESCE((SELECT SUM(c.amount_minor) FROM active c WHERE c.kind='credit' AND c.invoice_id=i.event_key),0))-COALESCE((SELECT SUM(h.amount_minor) FROM active h WHERE h.kind='hold' AND h.status='active' AND h.invoice_id=i.event_key),0)) AS unheld FROM active i WHERE i.kind='invoice' AND i.status='active' AND i.vendor='BLUE' AND date(i.due_date)<=date('2026-10-30')), rates AS (SELECT a.event_key,a.unheld,CASE WHEN date('2026-10-23')<=date(a.discount_until) THEN 10000-(SELECT t.discount_bps FROM active t WHERE t.kind='terms' AND t.status='active' AND t.terms_code=a.terms_code AND date(t.business_date)<=date(a.business_date) ORDER BY date(t.business_date) DESC LIMIT 1) ELSE 10000 END AS discount_factor,(SELECT f.fx_num FROM active f WHERE f.kind='fx' AND f.status='active' AND f.currency=a.currency AND date(f.business_date)<=date(a.business_date) ORDER BY date(f.business_date) DESC LIMIT 1) AS fx_num,(SELECT f.fx_den FROM active f WHERE f.kind='fx' AND f.status='active' AND f.currency=a.currency AND date(f.business_date)<=date(a.business_date) ORDER BY date(f.business_date) DESC LIMIT 1) AS fx_den FROM amounts a WHERE 1=1), rounded AS (SELECT event_key,unheld,discount_factor,fx_num,fx_den,CAST((2*unheld*discount_factor*fx_num+10000*fx_den)/(2*10000*fx_den) AS INTEGER) AS usd_cents FROM rates WHERE 1=1) SELECT event_key,unheld,discount_factor,fx_num,fx_den,usd_cents,SUM(usd_cents) OVER () AS total_usd_cents FROM rounded WHERE 1=1 ORDER BY event_key\"}}"}}
